<?php

declare(strict_types=1);

namespace App\Repositories;

use App\Core\Database;
use DomainException;
use PDO;

final class WorkflowRepository
{
    public function __construct(private readonly Database $db) {}

    public function promote(int $instituteId, int $fromClass, int $toClass, array $studentIds, int $userId): int
    {
        $ids = array_values(array_unique(array_filter(array_map('intval', $studentIds))));
        if (!$ids || $fromClass === $toClass) throw new DomainException('Select students and a different target class.');
        foreach ([$fromClass, $toClass] as $class) if (!$this->owned('classes', $class, $instituteId)) throw new DomainException('Invalid class.');
        $pdo = $this->db->connection(); $pdo->beginTransaction();
        try {
            $now = date('Y-m-d H:i:s'); $count = 0;
            foreach ($ids as $id) {
                $student = $this->db->query('SELECT class_id FROM students WHERE id=:id AND institute_id=:i FOR UPDATE', ['id'=>$id,'i'=>$instituteId])->fetch();
                if (!$student || (int)$student['class_id'] !== $fromClass) throw new DomainException('Student does not belong to the source class.');
                $this->db->query('UPDATE students SET class_id=:to,updated_at=:now WHERE id=:id', ['to'=>$toClass,'now'=>$now,'id'=>$id]);
                $this->db->query('INSERT INTO student_promotions(student_id,from_class_id,to_class_id,promoted_at,promoted_by) VALUES(:s,:f,:t,:at,:u)', ['s'=>$id,'f'=>$fromClass,'t'=>$toClass,'at'=>$now,'u'=>$userId]);
                $count++;
            }
            $pdo->commit(); return $count;
        } catch (\Throwable $e) { if ($pdo->inTransaction()) $pdo->rollBack(); throw $e; }
    }

    public function paySalary(int $instituteId, int $employeeId, string $month, float $paid, string $date, int $userId, float $adjustment=0, ?string $reference=null, ?string $remarks=null): int
    {
        if (!preg_match('/^\d{4}-(0[1-9]|1[0-2])$/', $month) || !$this->date($date) || $paid <= 0) throw new DomainException('Invalid salary payment.');
        $employee=$this->db->query('SELECT monthly_salary FROM employees WHERE id=:id AND institute_id=:i AND status="active"',['id'=>$employeeId,'i'=>$instituteId])->fetch();
        if(!$employee) throw new DomainException('Invalid employee.');
        try {$this->db->query('INSERT INTO salary_payments(employee_id,salary_month,base_salary,adjustment_amount,paid_amount,payment_date,reference,remarks,paid_by,created_at) VALUES(:e,:m,:b,:a,:p,:d,:r,:x,:u,:c)',['e'=>$employeeId,'m'=>$month,'b'=>$employee['monthly_salary'],'a'=>$adjustment,'p'=>$paid,'d'=>$date,'r'=>$reference,'x'=>$remarks,'u'=>$userId,'c'=>date('Y-m-d H:i:s')]);}
        catch(\PDOException $e){if($e->getCode()==='23000')throw new DomainException('Salary already paid for this period.');throw$e;}
        return (int)$this->db->connection()->lastInsertId();
    }

    public function salarySlip(int $id,int $instituteId):?array{$r=$this->db->query('SELECT sp.*,e.name,e.employee_no,e.role,i.name institute_name FROM salary_payments sp JOIN employees e ON e.id=sp.employee_id JOIN institutes i ON i.id=e.institute_id WHERE sp.id=:id AND e.institute_id=:i',['id'=>$id,'i'=>$instituteId])->fetch();return$r?:null;}
    public function salaryPayments(int$instituteId,int$employee=0):array{$sql='SELECT sp.*,e.name,e.employee_no FROM salary_payments sp JOIN employees e ON e.id=sp.employee_id WHERE e.institute_id=:i'.($employee?' AND e.id=:e':'').' ORDER BY sp.payment_date DESC,sp.id DESC LIMIT 100';$p=['i'=>$instituteId];if($employee)$p['e']=$employee;return$this->db->query($sql,$p)->fetchAll();}

    public function createExam(int $instituteId,string $name,string $start,string $end,int $userId):int{if(trim($name)===''||!$this->date($start)||!$this->date($end)||$start>$end)throw new DomainException('Invalid exam dates.');$now=date('Y-m-d H:i:s');$this->db->query('INSERT INTO exams(institute_id,name,start_date,end_date,created_by,created_at,updated_at) VALUES(:i,:n,:s,:e,:u,:c,:c2)',['i'=>$instituteId,'n'=>trim($name),'s'=>$start,'e'=>$end,'u'=>$userId,'c'=>$now,'c2'=>$now]);return(int)$this->db->connection()->lastInsertId();}
    public function exams(int$instituteId,int$limit=100):array{return$this->db->query('SELECT * FROM exams WHERE institute_id=:i ORDER BY start_date DESC,id DESC LIMIT '.max(1,min(100,$limit)),['i'=>$instituteId])->fetchAll();}
    public function deleteExam(int$instituteId,int$id):bool{return$this->db->query('DELETE FROM exams WHERE id=:id AND institute_id=:i',['id'=>$id,'i'=>$instituteId])->rowCount()>0;}
    public function examSetups(int$instituteId,int$exam=0,int$class=0):array{$sql='SELECT es.*,e.name exam_name,c.name class_name,s.name subject_name FROM exam_subjects es JOIN exams e ON e.id=es.exam_id JOIN classes c ON c.id=es.class_id JOIN subjects s ON s.id=es.subject_id WHERE e.institute_id=:i'.($exam?' AND e.id=:e':'').($class?' AND c.id=:c':'').' ORDER BY e.start_date DESC,c.name,s.name';$p=['i'=>$instituteId];if($exam)$p['e']=$exam;if($class)$p['c']=$class;return$this->db->query($sql,$p)->fetchAll();}
    public function examMarkSheet(int$instituteId,int$setup):array{return$this->db->query('SELECT st.id,st.registration_no,st.student_name,es.total_marks,em.obtained_marks FROM exam_subjects es JOIN exams e ON e.id=es.exam_id JOIN students st ON st.class_id=es.class_id LEFT JOIN exam_marks em ON em.exam_subject_id=es.id AND em.student_id=st.id WHERE es.id=:s AND e.institute_id=:i AND st.status="active" ORDER BY st.student_name',['s'=>$setup,'i'=>$instituteId])->fetchAll();}
    public function classResults(int$instituteId,int$examId,int$classId):array{return$this->db->query('SELECT st.id,st.registration_no,st.student_name,SUM(em.obtained_marks) obtained,SUM(es.total_marks) total,ROUND(SUM(em.obtained_marks)/NULLIF(SUM(es.total_marks),0)*100,2) percentage FROM students st JOIN exam_subjects es ON es.class_id=st.class_id AND es.exam_id=:e LEFT JOIN exam_marks em ON em.exam_subject_id=es.id AND em.student_id=st.id WHERE st.institute_id=:i AND st.class_id=:c GROUP BY st.id ORDER BY st.student_name',['e'=>$examId,'i'=>$instituteId,'c'=>$classId])->fetchAll();}

    public function setupExam(int $instituteId,int $examId,int $classId,int $subjectId,float $total):int
    {if($total<=0||!$this->owned('exams',$examId,$instituteId)||!$this->owned('classes',$classId,$instituteId)||!$this->subjectInClass($subjectId,$classId))throw new DomainException('Invalid exam setup.');$now=date('Y-m-d H:i:s');$this->db->query('INSERT INTO exam_subjects(exam_id,class_id,subject_id,total_marks,created_at,updated_at) VALUES(:e,:c,:s,:t,:n,:n2) ON DUPLICATE KEY UPDATE total_marks=VALUES(total_marks),updated_at=VALUES(updated_at)',['e'=>$examId,'c'=>$classId,'s'=>$subjectId,'t'=>$total,'n'=>$now,'n2'=>$now]);return(int)$this->db->connection()->lastInsertId();}

    public function saveExamMarks(int $instituteId,int $setupId,array $marks,int $userId):int
    {$setup=$this->db->query('SELECT es.total_marks,es.class_id FROM exam_subjects es JOIN exams e ON e.id=es.exam_id WHERE es.id=:id AND e.institute_id=:i',['id'=>$setupId,'i'=>$instituteId])->fetch();if(!$setup)throw new DomainException('Invalid exam setup.');$pdo=$this->db->connection();$pdo->beginTransaction();try{$now=date('Y-m-d H:i:s');$count=0;foreach($marks as $studentId=>$score){$score=(float)$score;if($score<0||$score>(float)$setup['total_marks'])throw new DomainException('Marks exceed the allowed total.');$ok=$this->db->query('SELECT 1 FROM students WHERE id=:s AND institute_id=:i AND class_id=:c',['s'=>(int)$studentId,'i'=>$instituteId,'c'=>$setup['class_id']])->fetchColumn();if(!$ok)throw new DomainException('Student does not belong to the exam class.');$this->db->query('INSERT INTO exam_marks(exam_subject_id,student_id,obtained_marks,entered_by,created_at,updated_at) VALUES(:e,:s,:m,:u,:n,:n2) ON DUPLICATE KEY UPDATE obtained_marks=VALUES(obtained_marks),entered_by=VALUES(entered_by),updated_at=VALUES(updated_at)',['e'=>$setupId,'s'=>(int)$studentId,'m'=>$score,'u'=>$userId,'n'=>$now,'n2'=>$now]);$count++;}$pdo->commit();return$count;}catch(\Throwable$e){if($pdo->inTransaction())$pdo->rollBack();throw$e;}}

    public function studentResult(int $instituteId,int $examId,int $studentId):array
    {$rows=$this->db->query('SELECT s.name subject,es.total_marks,em.obtained_marks FROM exam_marks em JOIN exam_subjects es ON es.id=em.exam_subject_id JOIN exams e ON e.id=es.exam_id JOIN subjects s ON s.id=es.subject_id JOIN students st ON st.id=em.student_id WHERE e.institute_id=:i AND e.id=:e AND st.institute_id=:i2 AND st.id=:s ORDER BY s.name',['i'=>$instituteId,'e'=>$examId,'i2'=>$instituteId,'s'=>$studentId])->fetchAll();$obt=array_sum(array_column($rows,'obtained_marks'));$total=array_sum(array_column($rows,'total_marks'));$pct=$total>0?$obt/$total*100:0;$grade=$this->db->query('SELECT grade,status FROM grading_rules WHERE institute_id=:i AND :p BETWEEN range_from AND range_to ORDER BY sort_order LIMIT 1',['i'=>$instituteId,'p'=>$pct])->fetch()?:null;return['subjects'=>$rows,'obtained'=>$obt,'total'=>$total,'percentage'=>$pct,'grade'=>$grade];}

    public function createCertificate(int $instituteId,string $template,string $type,?int $studentId,?int $employeeId,string $date,int $userId,?string $achievement):int
    {if(!in_array($type,['student','employee'],true)||!$this->date($date))throw new DomainException('Invalid certificate.');if($type==='student'){if(!$studentId||!$this->owned('students',$studentId,$instituteId)||$employeeId)throw new DomainException('Invalid recipient.');}else{if(!$employeeId||!$this->owned('employees',$employeeId,$instituteId)||$studentId)throw new DomainException('Invalid recipient.');}$this->db->query('INSERT INTO certificates(institute_id,template,recipient_type,student_id,employee_id,achievement,certificate_date,generated_by,created_at) VALUES(:i,:t,:r,:s,:e,:a,:d,:u,:c)',['i'=>$instituteId,'t'=>$template,'r'=>$type,'s'=>$studentId,'e'=>$employeeId,'a'=>$achievement,'d'=>$date,'u'=>$userId,'c'=>date('Y-m-d H:i:s')]);return(int)$this->db->connection()->lastInsertId();}

    public function certificates(int$instituteId):array{return$this->db->query('SELECT c.*,COALESCE(s.student_name,e.name) recipient_name FROM certificates c LEFT JOIN students s ON s.id=c.student_id LEFT JOIN employees e ON e.id=c.employee_id WHERE c.institute_id=:i ORDER BY c.certificate_date DESC,c.id DESC LIMIT 100',['i'=>$instituteId])->fetchAll();}
    public function deleteCertificate(int$instituteId,int$id):bool{return$this->db->query('DELETE FROM certificates WHERE id=:id AND institute_id=:i',['id'=>$id,'i'=>$instituteId])->rowCount()>0;}

    public function createHomework(int$instituteId,array$d,int$userId):int
    {$teacher=(int)($d['teacher_id']??0);$class=(int)($d['class_id']??0);$subject=(int)($d['subject_id']??0);$text=trim((string)($d['text']??''));$date=(string)($d['date']??'');if(!$this->date($date)||$text===''||!$this->owned('employees',$teacher,$instituteId)||!$this->owned('classes',$class,$instituteId)||!$this->subjectInClass($subject,$class))throw new DomainException('Invalid homework assignment.');$now=date('Y-m-d H:i:s');$this->db->query('INSERT INTO homework(homework_date,teacher_id,class_id,subject_id,homework_text,attachment_path,created_by,created_at,updated_at) VALUES(:d,:t,:c,:s,:x,:a,:u,:n,:n2)',['d'=>$date,'t'=>$teacher,'c'=>$class,'s'=>$subject,'x'=>$text,'a'=>$d['attachment']??null,'u'=>$userId,'n'=>$now,'n2'=>$now]);return(int)$this->db->connection()->lastInsertId();}

    public function homework(int$instituteId,?string$date=null,int$class=0,int$teacher=0):array{$sql='SELECT h.*,e.name teacher_name,c.name class_name,s.name subject_name FROM homework h JOIN employees e ON e.id=h.teacher_id JOIN classes c ON c.id=h.class_id JOIN subjects s ON s.id=h.subject_id WHERE c.institute_id=:i'.($date?' AND h.homework_date=:d':'').($class?' AND h.class_id=:c':'').($teacher?' AND h.teacher_id=:t':'').' ORDER BY h.homework_date DESC,h.id DESC LIMIT 100';$p=['i'=>$instituteId];if($date)$p['d']=$date;if($class)$p['c']=$class;if($teacher)$p['t']=$teacher;return$this->db->query($sql,$p)->fetchAll();}
    public function updateHomework(int$instituteId,int$id,array$d):bool{$teacher=(int)($d['teacher_id']??0);$class=(int)($d['class_id']??0);$subject=(int)($d['subject_id']??0);if(!$this->date((string)$d['date'])||trim((string)$d['text'])===''||!$this->owned('employees',$teacher,$instituteId)||!$this->owned('classes',$class,$instituteId)||!$this->subjectInClass($subject,$class))throw new DomainException('Invalid homework assignment.');return$this->db->query('UPDATE homework h JOIN classes c ON c.id=h.class_id SET h.homework_date=:d,h.teacher_id=:t,h.class_id=:cl,h.subject_id=:s,h.homework_text=:x,h.attachment_path=COALESCE(:a,h.attachment_path),h.updated_at=:n WHERE h.id=:id AND c.institute_id=:i',['d'=>$d['date'],'t'=>$teacher,'cl'=>$class,'s'=>$subject,'x'=>trim($d['text']),'a'=>$d['attachment']??null,'n'=>date('Y-m-d H:i:s'),'id'=>$id,'i'=>$instituteId])->rowCount()>0;}

    /** Class tests for the institute, with how many students have marks recorded. */
public function classTests(int$instituteId,int$class=0,int$subject=0):array{$sql='SELECT ct.*,c.name class_name,s.name subject_name,(SELECT COUNT(*) FROM class_test_marks m WHERE m.class_test_id=ct.id) marked FROM class_tests ct JOIN classes c ON c.id=ct.class_id JOIN subjects s ON s.id=ct.subject_id WHERE ct.institute_id=:i'.($class?' AND ct.class_id=:c':'').($subject?' AND ct.subject_id=:s':'').' ORDER BY ct.test_date DESC,ct.id DESC LIMIT 200';$p=['i'=>$instituteId];if($class)$p['c']=$class;if($subject)$p['s']=$subject;return$this->db->query($sql,$p)->fetchAll();}
public function classTest(int$instituteId,int$id):?array{$row=$this->db->query('SELECT ct.*,c.name class_name,s.name subject_name FROM class_tests ct JOIN classes c ON c.id=ct.class_id JOIN subjects s ON s.id=ct.subject_id WHERE ct.id=:id AND ct.institute_id=:i LIMIT 1',['id'=>$id,'i'=>$instituteId])->fetch();return is_array($row)?$row:null;}
/** Active students of the test's class with any marks already recorded, for the entry grid. */
public function classTestMarkSheet(int$instituteId,int$testId):array{$test=$this->classTest($instituteId,$testId);if(!$test)return[];return$this->db->query('SELECT st.id,st.registration_no,st.student_name,m.obtained_marks FROM students st LEFT JOIN class_test_marks m ON m.student_id=st.id AND m.class_test_id=:t WHERE st.class_id=:c AND st.institute_id=:i AND st.status="active" ORDER BY st.student_name',['t'=>$testId,'c'=>(int)$test['class_id'],'i'=>$instituteId])->fetchAll();}
public function updateClassTest(int$instituteId,int$id,string$title,string$date,float$total):bool{if(!$this->classTest($instituteId,$id))throw new DomainException('Class test not found.');if(trim($title)===''||!$this->date($date)||$total<=0)throw new DomainException('Enter a valid title, date and total marks.');if($this->db->query('SELECT 1 FROM class_test_marks WHERE class_test_id=:t AND obtained_marks>:m LIMIT 1',['t'=>$id,'m'=>$total])->fetchColumn())throw new DomainException('Existing marks exceed the new total. Correct the marks first.');return$this->db->query('UPDATE class_tests SET title=:t,test_date=:d,total_marks=:m WHERE id=:id AND institute_id=:i',['t'=>trim($title),'d'=>$date,'m'=>$total,'id'=>$id,'i'=>$instituteId])->rowCount()>=0;}
public function deleteClassTest(int$instituteId,int$id):bool{if(!$this->classTest($instituteId,$id))return false;$this->db->query('DELETE FROM class_tests WHERE id=:id AND institute_id=:i',['id'=>$id,'i'=>$instituteId]);return true;}
/** Deletes homework, scoped through its class so the institute check still applies. */
public function deleteHomework(int$instituteId,int$id):bool{$row=$this->db->query('SELECT h.id,h.attachment_path FROM homework h JOIN classes c ON c.id=h.class_id WHERE h.id=:id AND c.institute_id=:i',['id'=>$id,'i'=>$instituteId])->fetch();if(!is_array($row))return false;$this->db->query('DELETE FROM homework WHERE id=:id',['id'=>$id]);if(!empty($row['attachment_path'])){$p=BASE_PATH.'/public/'.$row['attachment_path'];if(is_file($p))@unlink($p);}return true;}
/** The employee record linked to a user, used to scope a teacher to their own work. */
public function employeeIdForUser(int$userId,int$instituteId):int{return(int)$this->db->query('SELECT e.id FROM employee_accounts ea JOIN employees e ON e.id=ea.employee_id WHERE ea.user_id=:u AND e.institute_id=:i LIMIT 1',['u'=>$userId,'i'=>$instituteId])->fetchColumn();}
public function createClassTest(int$instituteId,int$class,int$subject,string$date,string$title,float$total,int$userId):int
    {if(!$this->date($date)||trim($title)===''||$total<=0||!$this->owned('classes',$class,$instituteId)||!$this->subjectInClass($subject,$class))throw new DomainException('Invalid class test.');$now=date('Y-m-d H:i:s');$this->db->query('INSERT INTO class_tests(institute_id,class_id,subject_id,test_date,title,total_marks,created_by,created_at,updated_at) VALUES(:i,:c,:s,:d,:t,:m,:u,:n,:n2)',['i'=>$instituteId,'c'=>$class,'s'=>$subject,'d'=>$date,'t'=>trim($title),'m'=>$total,'u'=>$userId,'n'=>$now,'n2'=>$now]);return(int)$this->db->connection()->lastInsertId();}

    public function classTestResults(int$instituteId,int$class=0,int$subject=0,int$student=0,?string$from=null,?string$to=null):array{$sql='SELECT ct.id,ct.test_date,ct.title,ct.total_marks,c.name class_name,s.name subject_name,st.id student_id,st.registration_no,st.student_name,ctm.obtained_marks,ROUND(ctm.obtained_marks/ct.total_marks*100,2) percentage FROM class_test_marks ctm JOIN class_tests ct ON ct.id=ctm.class_test_id JOIN classes c ON c.id=ct.class_id JOIN subjects s ON s.id=ct.subject_id JOIN students st ON st.id=ctm.student_id WHERE ct.institute_id=:i'.($class?' AND ct.class_id=:c':'').($subject?' AND ct.subject_id=:s':'').($student?' AND st.id=:st':'').($from?' AND ct.test_date>=:f':'').($to?' AND ct.test_date<=:t':'').' ORDER BY ct.test_date DESC,st.student_name LIMIT 250';$p=['i'=>$instituteId];if($class)$p['c']=$class;if($subject)$p['s']=$subject;if($student)$p['st']=$student;if($from)$p['f']=$from;if($to)$p['t']=$to;return$this->db->query($sql,$p)->fetchAll();}

    public function saveClassTestMarks(int$instituteId,int$testId,array$marks,int$userId):int
    {$test=$this->db->query('SELECT class_id,total_marks FROM class_tests WHERE id=:id AND institute_id=:i',['id'=>$testId,'i'=>$instituteId])->fetch();if(!$test)throw new DomainException('Invalid class test.');$pdo=$this->db->connection();$pdo->beginTransaction();try{$now=date('Y-m-d H:i:s');$count=0;foreach($marks as$student=>$mark){$mark=(float)$mark;if($mark<0||$mark>(float)$test['total_marks']||!$this->db->query('SELECT 1 FROM students WHERE id=:s AND class_id=:c AND institute_id=:i',['s'=>(int)$student,'c'=>$test['class_id'],'i'=>$instituteId])->fetchColumn())throw new DomainException('Invalid test marks.');$this->db->query('INSERT INTO class_test_marks(class_test_id,student_id,obtained_marks,entered_by,created_at,updated_at) VALUES(:t,:s,:m,:u,:n,:n2) ON DUPLICATE KEY UPDATE obtained_marks=VALUES(obtained_marks),entered_by=VALUES(entered_by),updated_at=VALUES(updated_at)',['t'=>$testId,'s'=>(int)$student,'m'=>$mark,'u'=>$userId,'n'=>$now,'n2'=>$now]);$count++;}$pdo->commit();return$count;}catch(\Throwable$e){if($pdo->inTransaction())$pdo->rollBack();throw$e;}}

    public function createConversation(int$instituteId,int$sender,int$recipient,string$body,?string$subject=null):int
    {if($sender===$recipient||trim($body)===''||!$this->userInInstitute($recipient,$instituteId)||!$this->userInInstitute($sender,$instituteId))throw new DomainException('Invalid conversation.');$pdo=$this->db->connection();$pdo->beginTransaction();try{$now=date('Y-m-d H:i:s');$this->db->query('INSERT INTO conversations(institute_id,subject,created_by,created_at,updated_at) VALUES(:i,:s,:u,:n,:n2)',['i'=>$instituteId,'s'=>$subject,'u'=>$sender,'n'=>$now,'n2'=>$now]);$id=(int)$pdo->lastInsertId();foreach([$sender,$recipient]as$user)$this->db->query('INSERT INTO conversation_participants(conversation_id,user_id,last_read_at) VALUES(:c,:u,:r)',['c'=>$id,'u'=>$user,'r'=>$user===$sender?$now:null]);$this->db->query('INSERT INTO messages(conversation_id,sender_id,body,created_at) VALUES(:c,:u,:b,:n)',['c'=>$id,'u'=>$sender,'b'=>trim($body),'n'=>$now]);$pdo->commit();return$id;}catch(\Throwable$e){if($pdo->inTransaction())$pdo->rollBack();throw$e;}}

    public function conversations(int$instituteId,int$user):array{return$this->db->query('SELECT c.id,c.subject,c.updated_at,GROUP_CONCAT(CASE WHEN p2.user_id<>:u THEN u2.name END) participant_name,SUM(CASE WHEN m.sender_id<>:u2 AND (p.last_read_at IS NULL OR m.created_at>p.last_read_at) THEN 1 ELSE 0 END) unread_count FROM conversations c JOIN conversation_participants p ON p.conversation_id=c.id AND p.user_id=:u3 JOIN conversation_participants p2 ON p2.conversation_id=c.id JOIN users u2 ON u2.id=p2.user_id LEFT JOIN messages m ON m.conversation_id=c.id WHERE c.institute_id=:i GROUP BY c.id ORDER BY c.updated_at DESC LIMIT 100',['u'=>$user,'u2'=>$user,'u3'=>$user,'i'=>$instituteId])->fetchAll();}
    public function conversation(int$instituteId,int$id,int$user):?array{$allowed=$this->db->query('SELECT 1 FROM conversations c JOIN conversation_participants p ON p.conversation_id=c.id WHERE c.id=:id AND c.institute_id=:i AND p.user_id=:u',['id'=>$id,'i'=>$instituteId,'u'=>$user])->fetchColumn();if(!$allowed)return null;$this->db->query('UPDATE conversation_participants SET last_read_at=:n WHERE conversation_id=:c AND user_id=:u',['n'=>date('Y-m-d H:i:s'),'c'=>$id,'u'=>$user]);return['id'=>$id,'messages'=>$this->db->query('SELECT m.*,u.name sender_name FROM messages m JOIN users u ON u.id=m.sender_id WHERE m.conversation_id=:c ORDER BY m.created_at,m.id',['c'=>$id])->fetchAll()];}
    public function messageRecipients(int$instituteId,int$exclude):array{return$this->db->query('SELECT DISTINCT u.id,u.name,u.email FROM users u WHERE u.id<>:x AND u.status="active" AND (EXISTS(SELECT 1 FROM student_accounts sa JOIN students s ON s.id=sa.student_id WHERE sa.user_id=u.id AND s.institute_id=:i) OR EXISTS(SELECT 1 FROM employee_accounts ea JOIN employees e ON e.id=ea.employee_id WHERE ea.user_id=u.id AND e.institute_id=:i2)) ORDER BY u.name LIMIT 200',['x'=>$exclude,'i'=>$instituteId,'i2'=>$instituteId])->fetchAll();}

    public function sendMessage(int$instituteId,int$conversation,int$sender,string$body):int
    {if(trim($body)===''||!$this->db->query('SELECT 1 FROM conversations c JOIN conversation_participants p ON p.conversation_id=c.id WHERE c.id=:c AND c.institute_id=:i AND p.user_id=:u',['c'=>$conversation,'i'=>$instituteId,'u'=>$sender])->fetchColumn())throw new DomainException('Conversation access denied.');$now=date('Y-m-d H:i:s');$this->db->query('INSERT INTO messages(conversation_id,sender_id,body,created_at) VALUES(:c,:u,:b,:n)',['c'=>$conversation,'u'=>$sender,'b'=>trim($body),'n'=>$now]);$id=(int)$this->db->connection()->lastInsertId();$this->db->query('UPDATE conversations SET updated_at=:n WHERE id=:c',['n'=>$now,'c'=>$conversation]);return$id;}

    public function createLiveClass(int $instituteId,array $data,int $userId):int
    {$type=(string)($data['type']??'');if(!in_array($type,['AS','AT','SC','SS','ST'],true)||trim((string)($data['title']??''))===''||trim((string)($data['code']??''))==='')throw new DomainException('Invalid live class.');$targets=['SC'=>['classes','class'],'SS'=>['students','student'],'ST'=>['employees','teacher']];$class=$student=$employee=null;if(isset($targets[$type])){[$table,$key]=$targets[$type];$id=(int)($data[$key]??0);if(!$id||!$this->owned($table,$id,$instituteId))throw new DomainException('Invalid audience target.');if($type==='SC')$class=$id;if($type==='SS')$student=$id;if($type==='ST')$employee=$id;}$scheduled=null;if(!empty($data['schedule'])){$scheduled=trim((string)($data['date']??'').' '.(string)($data['time']??''));if(!strtotime($scheduled)||strtotime($scheduled)<=time())throw new DomainException('Scheduled time must be in the future.');}$now=date('Y-m-d H:i:s');$this->db->query('INSERT INTO live_classes(institute_id,title,room_code,audience_type,target_class_id,target_student_id,target_employee_id,scheduled_at,duration_minutes,message,created_by,created_at,updated_at) VALUES(:i,:t,:r,:a,:c,:s,:e,:at,:d,:m,:u,:n,:n2)',['i'=>$instituteId,'t'=>trim($data['title']),'r'=>trim($data['code']),'a'=>$type,'c'=>$class,'s'=>$student,'e'=>$employee,'at'=>$scheduled,'d'=>(int)($data['duration']??0)?:null,'m'=>trim((string)($data['message']??''))?:null,'u'=>$userId,'n'=>$now,'n2'=>$now]);return(int)$this->db->connection()->lastInsertId();}

    private function owned(string$table,int$id,int$institute):bool{if(!in_array($table,['classes','students','employees','exams'],true))return false;return(bool)$this->db->query("SELECT 1 FROM {$table} WHERE id=:id AND institute_id=:i",['id'=>$id,'i'=>$institute])->fetchColumn();}
    private function subjectInClass(int$subject,int$class):bool{return(bool)$this->db->query('SELECT 1 FROM class_subjects WHERE class_id=:c AND subject_id=:s',['c'=>$class,'s'=>$subject])->fetchColumn();}
    private function userInInstitute(int$user,int$institute):bool{return(bool)$this->db->query('SELECT 1 FROM users u WHERE u.id=:u AND (EXISTS(SELECT 1 FROM student_accounts sa JOIN students s ON s.id=sa.student_id WHERE sa.user_id=u.id AND s.institute_id=:i) OR EXISTS(SELECT 1 FROM employee_accounts ea JOIN employees e ON e.id=ea.employee_id WHERE ea.user_id=u.id AND e.institute_id=:i2) OR EXISTS(SELECT 1 FROM institute_users iu WHERE iu.user_id=u.id AND iu.institute_id=:i3))',['u'=>$user,'i'=>$institute,'i2'=>$institute,'i3'=>$institute])->fetchColumn();}
    private function date(string$value):bool{$d=\DateTimeImmutable::createFromFormat('!Y-m-d',$value);return$d!==false&&$d->format('Y-m-d')===$value;}
}
